import React, { useMemo, useState } from 'react';
import styled from 'styled-components';

import { getAppId, getAppName } from '@dynatrace-sdk/app-environment';

import { useFallbackIcon } from './hooks/useFallbackIcon.js';
import type { AriaLabelingProps } from '../../core/types/a11y-props.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import type { WithChildren } from '../../core/types/with-children.js';

// #region Typings
export interface AppIconProps
  extends AriaLabelingProps,
    WithChildren,
    StylingProps,
    DataTestId {
  /**
   * The path to the app icon. If not specified, the icon from the app registry is retrieved automatically.
   */
  src?: string;
  /**
   * The alternative text representation for the image when it's not loaded. If not specified, the app name is used.
   */
  alt?: string;
}
// #endregion

// #region Styled Components
const StyledAppIcon = styled.img({
  objectFit: 'contain',
});
// #endregion

/**
 * The `AppIcon` component renders the icon used for the app on the platform.
 * You can also provide a link to an icon to render that icon instead.
 */
export const AppIcon = (props: AppIconProps) => {
  const sdkAppId = useMemo(getAppId, []);
  const {
    src = `/platform/app-engine/registry/v1/app-icons/${sdkAppId}`,
    alt,
    children,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
    ...remainingProps
  }: AppIconProps = props;

  const [loadingFailed, setLoadingFailed] = useState(false);
  const fallbackIcon = useFallbackIcon(getAppName?.() || '', 20);

  if (loadingFailed) {
    return fallbackIcon; // This prevents flickering in case of failed image requests, because we are trying to measure the ActionGroup width including the icon width and if we return null, it would need to recalculate and re-render
  }

  return (
    <StyledAppIcon
      src={src}
      onError={() => setLoadingFailed(true)}
      data-testid={dataTestId}
      width={20}
      height={20}
      alt={alt}
      className={consumerClassName}
      style={consumerStyle}
      {...remainingProps}
    />
  );
};

AppIcon.displayName = 'AppHeader.AppIcon';
